import { strict as assert } from 'node:assert';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';
import { seedLibrary } from './seedLibrary.js';
import type { Move } from './types.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const projectRoot = resolve(__dirname, '..', '..');

/**
 * Ruleset chapter parsing — reads the V0.6 ruleset directly from the doc
 * so the test failures survive any repo re-org of the source document.
 */

interface ParsedMoveHeading {
  title: string;
  /** Single virtue text as shown in the ruleset parentheses, e.g. `[ 'Wit' ]` or `[ 'Wit', 'Heart' ]`.
   *  Empty array means the heading has no parenthetical or its content was `(Any)`.             */
  virtues: string[];
}

/** Which library virtue a single-name move gets. The library's own `Virtue.Name` values are the
 *  ground-truth for the names used below — they must match what the ruleset headers say.  */
const VIRTUE_KEY_MAP = Object.freeze({
  Might: 'v-might',
  Mettle: 'v-mettle',
  Heart: 'v-heart',
  Wit: 'v-wit',
  Guile: 'v-guile',
});

/** Extract the Basic Moves chapter from the ruleset text. The chapter starts at `# Basic Moves`
 *  and ends at the next `# Adventure Moves` heading — both are `# ` followed by a word, matching
 *  what the current doc headers look like, and they are distinct enough not to over-match. */
function extractBasicMovesChapter(text: string): string {
  const startMatch = text.match(/^# Basic Moves\s*$/m);
  if (!startMatch) {
    throw new Error('Could not find "# Basic Moves" heading in ruleset');
  }
  const afterStart = text.slice(startMatch.index! + startMatch[0].length);
  const endIdx = afterStart.search(/^# Adventure Moves\s*$/m);
  if (endIdx === -1) {
    throw new Error('Could not find "# Adventure Moves" heading after "# Basic Moves"');
  }
  return afterStart.slice(0, endIdx);
}

/** Parse all move headings in a ruleset chapter text. A heading is `## <Name> <(Virtues)>` where
 *  Virtues may be a single virtue, slash-separated virtues, or the keyword `Any`.              */
function parseBasicMovesChapter(chapter: string): ParsedMoveHeading[] {
  // Match lines starting with `## ` that contain `( ` — these are move headings.
  const headingRegex = /^## (.*?)(?:\(Any\)|\(([^)]+)\))\s*$/gm;
  const headings: ParsedMoveHeading[] = [];
  let match: RegExpExecArray | null;

  while ((match = headingRegex.exec(chapter)) !== null) {
    const rawName = match[1].trim();
    // Ruleset has a stray backslash-dash on "Offer Solace \- (Heart)"
    const name = rawName.replace(/\\\s*-/, '').trim();
    if (!name) continue;
    const virtues = match[2]?.split('/').map((v) => v.trim()) ?? [];
    headings.push({ title: name, virtues });
  }

  return headings;
}

/** The expected move data derived from parsing the ruleset.  */
function expectedBasicMoves(headings: ParsedMoveHeading[]): {
  title: string;
  virtueId: string | null;
}[] {
  return headings.map((h) => {
    // Any virtue (from `(Any)` heading or multi-virtue like `(Wit/Heart)`) => null
    if (h.virtues.length === 0 || h.virtues.length > 1) {
      return { title: h.title, virtud: null };
    }
    const singleVirtue = h.virtues[0];
    return { title: h.title, virtueId: VIRTUE_KEY_MAP[singleVirtue as keyof typeof VIRTUE_KEY_MAP] ?? null };
  });
}

/** Validate that every seeded Basic Move passes the conformance check.
 *  This file MUST fail when any seeded VirtueId diverges from what the ruleset headings say.   */
describe('seedLibrary basic moves conformance', () => {
  let rulesetText: string;
  let parsedHeadings: ParsedMoveHeading[];
  let expected: { title: string; virtueId: string | null }[];

  before(() => {
    rulesetText = readFileSync(
      resolve(projectRoot, 'Planning Docs', 'Ruleset-V0.6.md'),
      'utf-8',
    );
    const chapter = extractBasicMovesChapter(rulesetText);
    parsedHeadings = parseBasicMovesChapter(chapter);
    expected = expectedBasicMoves(parsedHeadings);
  });

  it('every parsed Basic Moves heading has a corresponding seeded Basic Move', () => {
    const seedMoves = seedLibrary().moves;
    for (const exp of expected) {
      const found = seedMoves.find(
        (m) => m.Name === exp.title && m.Kind === 'Basic',
      );
      assert.ok(
        found,
        `No seeded Basic Move named "${exp.title}" — heading exists in ruleset but seed is missing it`,
      );
    }
  });

  it('every seeded Basic Move VirtueId matches the ruleset heading', () => {
    const seedMoves = seedLibrary().moves.filter(
      (m) => m.Kind === 'Basic',
    );

    for (const exp of expected) {
      const seed = seedMoves.find(
        (m) => m.Name === exp.title && m.Kind === 'Basic',
      );
      assert.ok(
        seed,
        `Seed missing for "${exp.title}" (checked in title test; this is a backup)`,
      );
      assert.strictEqual(
        seed.VirtueId,
        exp.virtueId,
        `Move "${exp.title}": expected VirtueId ${JSON.stringify(exp.virtueId)} (from ruleset heading), got ${JSON.stringify(seed.VirtueId)}`,
      );
    }
  });
});

