import { strict as assert } from 'node:assert';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';
import { describe, it } from 'vitest';
import { seedLibrary } from './seedLibrary.js';
import type { Move } from './types.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const projectRoot = resolve(__dirname, '..', '..');

/** Ruleset chapter parsing reads the V0.6 ruleset directly so test failures survive any
 *  repo re-org of the source document.
 */

interface ParsedMoveHeading {
  title: string;
  virtues: string[];
  /** Whether the heading has no parenthetical or its content is `(Any)`. In both cases
   *  the move has no single assigned virtue — VirtueId should be null.                          */
  isAny: boolean;
}

/** Which library virtue a single-name move gets. These values must match what the
 *  library's seed data already defines in its Virtue.Name values.            */
const VIRTUE_KEY_MAP = Object.freeze({
  Might: 'v-might',
  Mettle: 'v-mettle',
  Heart: 'v-heart',
  Wit: 'v-wit',
  Guile: 'v-guile',
});

/** Extract the Basic Moves chapter text from the ruleset. */
function extractBasicMovesChapter(text: string): string {
  const start = text.match(/^# Basic Moves\s*$/m);
  if (!start) throw new Error('Could not find "# Basic Moves" heading');
  const afterStart = text.slice(start.index! + start[0].length);
  const end = afterStart.search(/^# Adventure Moves\s*$/m);
  if (end === -1) throw new Error('Could not find "# Adventure Moves" heading');
  return afterStart.slice(0, end);
}

/** Parse all `## Move (Virtues)` headings from a chapter. */
function parseBasicMovesChapter(chapter: string): ParsedMoveHeading[] {
  const re = /^## (.*?)(?:\(Any\)|\(([^)]+)\))\s*$/gm;
  const results: ParsedMoveHeading[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(chapter)) !== null) {
    let name = m[1].trim().replace(/\\\s*-/, '').trim();
    if (!name) continue;
    const virtues = m[2] !== undefined && m[2].trim() ? m[2].trim().split('/').map((v) => v.trim()) : [];
    results.push({ title: name, virtues, isAny: m[3] !== undefined && m[3].trim() === 'Any' });
  }
  return results;
}

function makeExpected(headings: ParsedMoveHeading[]): { title: string; virtueId: string | null }[] {
  return headings.map((h) => {
    if (h.isAny || h.virtues.length !== 1) return { title: h.title, virtueId: null };
    return { title: h.title, virtueId: VIRTUE_KEY_MAP[h.virtues[0] as keyof typeof VIRTUE_KEY_MAP] ?? null };
  });
}

/** Read the ruleset file, parse headings, return parsed data. Cached per describe block. */
function loadBasicMoves(): { parsed: ParsedMoveHeading[]; expected: { title: string; virtueId: string | null }[] } {
  const text = readFileSync(resolve(projectRoot, 'Planning Docs', 'Ruleset-V0.6.md'), 'utf-8');
  const chapter = extractBasicMovesChapter(text);
  return { parsed: parseBasicMovesChapter(chapter), expected: makeExpected(parseBasicMovesChapter(chapter)) };
}

describe('seedLibrary basic moves conformance', () => {
  const { parsed, expected } = loadBasicMoves();

  it('every parsed Basic Moves heading has a corresponding seeded Basic Move', () => {
    const seeded = seedLibrary().moves;
    for (const exp of expected) {
      const found = seeded.find((m) => m.Name === exp.title && m.Kind === 'Basic');
      assert.ok(
        found,
        `No seeded Basic Move named "${exp.title}" — heading exists in ruleset but seed is missing it`,
      );
    }
  });

  it('every seeded Basic Move VirtueId matches the ruleset heading', () => {
    const seeded = seedLibrary().moves.filter((m) => m.Kind === 'Basic');
    for (const exp of expected) {
      const seed = seeded.find((m) => m.Name === exp.title && m.Kind === 'Basic');
      assert.ok(
        seed,
        `Seed missing for "${exp.title}" (should have been caught in title test)`,
      );
      assert.strictEqual(
        seed.VirtueId,
        exp.virtueId,
        `Move "${exp.title}": expected VirtueId ${JSON.stringify(exp.virtueId)}, got ${JSON.stringify(seed.VirtueId)}`,
      );
    }
  });
});

